def blocks(g):
    seen=[[False]*len(g[0]) for _ in g]; out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; comp=[]
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<len(g) and 0<=y<len(g[0]) and g[x][y] and not seen[x][y]:
                            seen[x][y]=True; st.append((x,y))
                out.append(comp)
    return out
def transform(g):
    g=[r[:] for r in g]; comps=blocks(g)
    tgt=min(comps, key=lambda c: sum(1 for a,b in c if g[a][b]==9))
    for a,b in tgt: g[a][b]=0
    return g
